const item = $json;
const title = String(item.title || '').trim();
const url = String(item.link || item.guid || '').trim();
const text = String(item.contentSnippet || item.content || item.description || '').replace(/\s+/g, ' ').trim();

return [{
  json: {
    dedupe_key: url || title.toLowerCase(),
    source: 'rss',
    source_title: title,
    source_url: url,
    published_at: item.isoDate || item.pubDate || null,
    source_text: text.slice(0, 12000)
  }
}];

const raw = $json.choices?.[0]?.message?.content || '{}';
let analysis;
try {
  analysis = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error('Gateway returned invalid JSON: ' + String(raw).slice(0, 500));
}

const original = $('Normalize source item').item.json;
return [{
  json: {
    ...original,
    ...analysis,
    ai_model: $json.model || $env.AI_MODEL || 'auto',
    raw_analysis: analysis
  }
}];

const relevant = $json.relevant === true;
const confidence = Number($json.confidence || 0);
const quality = Number($json.quality_score || 0);

if (!relevant || confidence < 0.65 || quality < 0.65) {
  return [];
}

const escapeSql = (value) => String(value ?? '').replace(/'/g, "''");
const rawJson = JSON.stringify($json.raw_analysis || {}).replace(/'/g, "''");
const published = $json.published_at ? `'${escapeSql($json.published_at)}'` : 'NULL';

const sql = `INSERT INTO content_candidates (dedupe_key, source, source_title, source_url, published_at, relevant, confidence, quality_score, draft_title, draft_text, status, ai_model, raw_analysis) VALUES ('${escapeSql($json.dedupe_key)}', '${escapeSql($json.source)}', '${escapeSql($json.source_title)}', '${escapeSql($json.source_url)}', ${published}, TRUE, ${confidence}, ${quality}, '${escapeSql($json.draft_title)}', '${escapeSql($json.draft_text)}', 'pending_review', '${escapeSql($json.ai_model)}', '${rawJson}'::jsonb) ON CONFLICT (dedupe_key) DO NOTHING;`;

const telegramText = `📝 <b>Новий кандидат на публікацію</b>\n\n<b>${String($json.draft_title || '').replace(/[&<>]/g, '')}</b>\n\n${String($json.draft_text || '').replace(/[&<>]/g, '')}\n\n<b>Оцінки:</b> relevance ${confidence.toFixed(2)}, quality ${quality.toFixed(2)}\n<b>Причина:</b> ${String($json.reason || '').replace(/[&<>]/g, '')}\n\n🔗 ${$json.source_url}`;

return [{ json: { ...$json, sql, telegram_text: telegramText } }];
